function matchesMonitor(e){const q=els.search.value.trim().toLowerCase(),df=els.deviceFilter.value,ch=els.channelFilter.value,ty=els.typeFilter.value;if(df&&e.deviceId!==df)return false;if(ch&&String(e.channel)!==ch)return false;if(ty&&e.kind!==ty)return false;return !q||JSON.stringify([e.device,e.label,e.kind,e.value,e.decimal,e.hex,e.channel,e.a]).toLowerCase().includes(q)}
