function renderMessages(){els.messageStats.innerHTML=meterRows(Object.entries(state.messageCounts).sort((a,b)=>b[1]-a[1]));const cs=channelStats(state.events),rows=[];for(const [ch,v] of Object.entries(cs))rows.push(['Ch '+ch+' · notes '+v.noteon+' · CC '+v.cc+' · bend '+v.pitchbend,v.total]);els.channels.innerHTML=meterRows(rows)}
