function reportRow(label,value){return '<tr><th scope="row">'+esc(label)+'</th><td>'+esc(value)+'</td></tr>'}
function renderComparison(c,old,cur){const sign=v=>(v>0?'+':'')+v;const changed=Object.entries(c.controls).filter(([,v])=>v.missing||v.new||v.rangeDelta||Math.abs(v.jitterDelta)>=0.5);return '<h3>Baseline comparison</h3><p class="muted">Compared with report generated '+esc(old.generatedAt||'(unknown time)')+(old.device?' for '+esc(old.device):'')+'.</p><table class="report-table">'+reportRow('Keys missing vs baseline',c.missingKeys.length?c.missingKeys.map(noteName).join(', '):'none')+reportRow('New keys vs baseline',c.newKeys.length)+reportRow('Disconnect delta',sign(c.disconnectDelta))+reportRow('Pitch-bend center delta',sign(c.pitchCenterDelta))+reportRow('Latency median delta (ms)',sign(Number(c.latencyMedianDelta.toFixed(2))))+reportRow('Peak message rate delta',sign(Number(c.peakRateDelta.toFixed(1))))+'</table>'+(changed.length?'<h4>Control changes</h4><table class="report-table">'+changed.slice(0,40).map(([k,v])=>reportRow(k,v.missing?'not observed this session':v.new?'new this session':'range '+sign(v.rangeDelta)+', jitter '+sign(v.jitterDelta))).join('')+'</table>':'<p>No control range/jitter changes.</p>')}
