const ctrlTable=ctrl.length?'<h3>Controls</h3><table class="report-table"><thead><tr><th>Control</th><th>Range</th><th>Coverage</th><th>Jitter</th><th>Jumps</th><th>Type</th></tr></thead><tbody>'+ctrl.slice(0,64).map(([k,v])=>'<tr><td>'+esc(k)+'</td><td>'+fmtRange(v.min,v.max)+'</td><td>'+v.coverage+'%</td><td>'+v.jitter+'</td><td>'+v.jumps+'</td><td>'+esc(v.encoder)+'</td></tr>').join('')+'</tbody></table>':'';
