const viewRenderers={quick:()=>{renderFindings();renderInventory()},monitorView:()=>{renderMessages();renderSysex()},controlsView:()=>{renderControls();renderPitch();renderMpe()},keyboardView:renderKeyboard,timingView:renderTiming,outputView:()=>{},testsView:renderTests,winlogView:renderWin,mappingView:renderLearn,reportView:renderReport};
function activeView(){return document.querySelector('.view.active-view')?.id||'quick'}
// force=true renders every view (used after resets and before print/export); otherwise only the visible view.
function renderAll(force=false){renderSummary();if(force){for(const f of Object.values(viewRenderers))f()}else viewRenderers[activeView()]?.();els.elapsed.textContent=formatElapsed(Date.now()-state.started)}
function download(name,text,type='text/plain'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(rows){return rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n')}
function send(bytes){if(!currentOutput){setStatus('Select a MIDI output first.','attention');return false}currentOutput.send(bytes);return true}
function outChannel(){return clamp(els.outChannel.value,1,16)-1}
function sendNote(on){send([(on?0x90:0x80)|outChannel(),clamp(els.outNote.value,0,127),on?clamp(els.outVelocity.value,0,127):0])}
function sendCc(){send([0xB0|outChannel(),clamp(els.outCc.value,0,127),clamp(els.outCcValue.value,0,127)])}
function sendProgram(){send([0xC0|outChannel(),clamp(els.outProgram.value,0,127)])}
