function runLoopback(){state.testWindowStart=Date.now();if(!currentInput||!currentOutput){setStatus('Select both an input and an output for loopback.','attention');return}if(state.loopback?.active){setStatus('Loopback already running.','attention');return}const ch=outChannel(),rounds=clamp(els.loopRounds.value,1,20),messages=[];for(let r=0;r<rounds;r++){const n=(60+r)&0x7f,seq=(r*7+17)&0x7f,pb=(8192+(r+1)*256)&0x3fff;messages.push([0x90|ch,n,37+r],[0x80|ch,n,0],[0xB0|ch,21,seq],[0xC0|ch,(9+r)&0x7f],[0xE0|ch,pb&0x7f,pb>>7],[0xB0|ch,21,(seq+86)&0x7f])}messages.push([0xE0|ch,0,64]);state.loopback={active:true,sent:messages.map(bytes=>({bytes,t:null,matched:false})),received:[],started:performance.now(),result:null};state.latencies=[];els.runLoopback.disabled=true;messages.forEach((m,i)=>setTimeout(()=>{const item=state.loopback?.sent[i];if(!item||!currentOutput)return;item.t=performance.now();currentOutput.send(m);if(i===messages.length-1)setTimeout(finishLoopback,700)},i*40));setStatus('Loopback sequence sending ('+messages.length+' messages); waiting for returned messages.','connected')}
