function guidedRender(){const step=guidedSteps[state.guidedStep]||guidedSteps.at(-1);els.guidedTitle.textContent=state.guided?(state.guidedStep+1)+'/'+guidedSteps.length+' · '+step[0]:'Ready';els.guidedText.textContent=state.guided?step[1]:'Enable MIDI and select an input, or use the monitor directly.';els.guided.textContent=state.guided?'Restart Guided Test':'Start Guided Test';els.guidedBack.disabled=!state.guided||state.guidedStep===0;els.guidedNext.disabled=!state.guided||state.guidedStep===guidedSteps.length-1;els.guidedSkip.disabled=!state.guided||state.guidedStep===guidedSteps.length-1;els.guidedEnd.disabled=!state.guided;if(state.guidedEnded){els.guidedTitle.textContent='Guided test ended';els.guidedText.textContent='Data is kept. Review the Report tab'+(state.guidedSkipped.length?' — skipped: '+state.guidedSkipped.join(', '):'')+'.'}}
function startGuided(){resetState(true);state.guided=true;state.guidedEnded=false;state.guidedStep=0;state.guidedSkipped=[];guidedRender();const hints={'Keyboard Controller':' Emphasize key sweep, velocity, pedals and pitch bend.','Pad Controller':' Emphasize pad coverage, velocity consistency and aftertouch.','DJ Controller':' Emphasize encoders, faders, buttons and message flood behavior.','Foot Controller':' Emphasize pedals, switches and reconnect stability.','Hardware Synth':' Emphasize bidirectional output, program changes, SysEx and clock.'};els.guidedText.textContent+=hints[els.preset.value]||'';setStatus('Guided diagnostic started.','connected')}
