const sevClass=s=>s==='investigate'?'investigate':s==='attention'?'attention':'';
function renderWin(){
 const a=state.winAnalysis,out=[];
 if(!a&&!state.logAnalyses.length)out.push('<article class="panel"><h2>No Windows scan yet</h2><p>'+(desktop?.platform==='win32'?'Press Scan Windows logs, or run a test: the scan runs automatically afterwards.':'This view analyses Windows logs. In a browser: press <strong>Copy PowerShell scan</strong>, paste it into a PowerShell window on the Windows PC (it is read-only and saves miditest-windows-scan.json to the Desktop), then use <strong>Import scan / log file</strong>. You can also import setupapi.dev.log (C:\\Windows\\INF) or a WER Report.wer file to have it explained.')+'</p></article>');
 if(a){
  out.push('<article class="panel"><div class="section-head"><div><h2>Scan summary</h2><p>'+esc(a.meta.os||'Windows')+' · scanned '+esc(a.meta.generated||'')+' · last '+esc(a.meta.days)+' day(s) · '+a.meta.eventsRead+' relevant event(s) read</p></div><span class="status-chip status-'+a.status+'">'+esc(a.status==='ok'?'No MIDI/USB errors found':a.status==='investigate'?'Investigate':'Attention')+'</span></div><div class="metric-grid">'+metric('Investigate',a.counts.investigate)+metric('Attention',a.counts.attention)+metric('Info',a.counts.info)+metric('During this test',a.counts.duringTest)+'</div>'+(a.meta.errors.length?'<p class="muted">Some logs could not be read (normal without Administrator rights): '+esc(a.meta.errors.slice(0,4).join(' | '))+'</p>':'')+'</article>');
  out.push('<article class="panel"><h2>Findings and what they mean</h2>'+(a.findings.length?a.findings.slice(0,60).map(f=>'<div class="win-finding"><span class="tag '+(f.duringTest?'now':'')+'">'+esc(f.severity)+'</span>'+(f.duringTest?'<span class="tag now">during this test</span>':'')+(f.mentionsDevice?'<span class="tag">mentions your device</span>':'')+'<h3>'+esc(f.title)+'</h3><p class="win-src">'+esc(f.category)+' · '+esc(f.source)+(f.time?' · '+esc(f.time):'')+'</p><p><strong>What it means:</strong> '+esc(f.explain)+'</p><p><strong>What to do:</strong> '+esc(f.action)+'</p>'+(f.raw?'<details><summary>Original log text</summary><pre>'+esc(f.raw)+'</pre></details>':'')+'</div>').join(''):'<p>No MIDI- or USB-related errors were found in the scanned logs. That does not rule out a device fault; it means Windows itself did not log one.</p>')+'</article>');
  if(a.devices.length)out.push('<article class="panel"><h2>MIDI / USB audio devices known to Windows</h2><div class="compact-table">'+a.devices.map(d=>'<div class="compact-row"><strong>'+esc(d.name||'Unknown')+'</strong><small>'+(d.errorCode?'Code '+d.errorCode+' — '+esc(d.problem?.title||''):'Working')+(d.driver?' · driver '+esc(d.driver.version||'?')+' ('+esc(d.driver.provider||'?')+', '+esc(d.driver.date||'?')+(d.driver.signed===false?', UNSIGNED':'')+')':'')+'</small><span>'+esc(d.class||'')+'</span></div>').join('')+'</div></article>');
  if(a.logs.length)out.push('<article class="panel"><h2>Log entries read</h2>'+a.logs.map(l=>'<div class="win-finding"><p class="win-src">'+esc(l.name)+(l.time?' · '+esc(l.time):'')+'</p><p>'+esc(l.summary)+'</p>'+(l.detail?'<pre>'+esc(l.detail)+'</pre>':'')+(l.action?'<p><strong>What to do:</strong> '+esc(l.action)+'</p>':'')+'</div>').join('')+'</article>');
 }
 for(const l of state.logAnalyses)out.push('<article class="panel"><h2>'+esc(l.name)+'</h2><p>'+esc(l.summary)+'</p>'+(l.findings.length?l.findings.map(f=>'<div class="win-finding"><span class="tag">'+esc(f.severity)+'</span><h3>'+esc(f.title)+'</h3><p><strong>What it means:</strong> '+esc(f.explain)+'</p><p><strong>What to do:</strong> '+esc(f.action)+'</p></div>').join(''):'<p>Nothing MIDI/USB-related stood out in this file.</p>')+'</article>');
 const html=out.join('');if(html!==renderWin.last){renderWin.last=html;els.winResults.innerHTML=html}
}
async function importWinFile(){
 const file=els.winImport.files?.[0];if(!file)return;els.winImport.value='';
 try{
  if(/\.evtx$/i.test(file.name))throw new Error('.evtx is a binary format. In Event Viewer use Save All Events As… > CSV or text, or use the PowerShell scan.');
  if(file.size>8*1024*1024)throw new Error('File is larger than 8 MB; import the last part of the log.');
  const text=await file.text();
  if(/\.json$/i.test(file.name)||text.trimStart().startsWith('{')){const obj=JSON.parse(text.replace(/^\uFEFF/,''));if(!obj||typeof obj!=='object'||(!obj.events&&!obj.devices&&!obj.setupapi))throw new Error('Not a MIDItest Windows scan file.');applyScan(obj);els.winStatus.textContent='Imported scan from '+file.name+'.'}
  else{const r=analyzeLogText(file.name,text);state.logAnalyses.push({name:file.name,type:r.type,summary:r.summary,findings:r.findings});if(state.logAnalyses.length>10)state.logAnalyses.shift();renderWin();els.winStatus.textContent='Explained '+file.name+' ('+r.type+').'}
 }catch(e){els.winStatus.textContent='Could not import: '+(e?.message||e)}
}
